export interface PageProps { navigate: (path: string) => void; query?: string; setTitle?: (title: string) => void }

const subjectColors: Record<string, string> = {
  Physics: "#72d9e8", Chemistry: "#9f91ff", Biology: "#90d9ba", Mathematics: "#f2c56f", "Earth Science": "#85bba1", Space: "#96a4ff", Engineering: "#f29b81",
};
const smallSource = (label: string, href: string) => <a className="sourceLink" href={href} target="_blank" rel="noreferrer">{label}<ExternalLink size={12}/></a>;

function Eyebrow({ children, dot = true }: { children: ReactNode; dot?: boolean }) { return <div className="eyebrow">{dot && <span className="eyebrowDot"/>}{children}</div>; }
function PageHeader({ kicker, title, description, right }: { kicker: string; title: ReactNode; description: string; right?: ReactNode }) { return <div className="pageHeader"><div><Eyebrow>{kicker}</Eyebrow><h1>{title}</h1><p>{description}</p></div>{right && <div className="pageHeaderActions">{right}</div>}</div>; }
function SectionHeading({ eyebrow, title, action }: { eyebrow?: string; title: string; action?: ReactNode }) { return <div className="sectionHeading"><div>{eyebrow && <div className="sectionEyebrow">{eyebrow}</div>}<h2>{title}</h2></div>{action}</div>; }
function GlassCard({ children, className = "", ...props }: React.HTMLAttributes<HTMLDivElement>) { return <div className={`glassCard ${className}`} {...props}>{children}</div>; }
function Button({ children, onClick, variant = "secondary", className = "", type = "button", disabled, ...props }: React.ButtonHTMLAttributes<HTMLButtonElement> & { variant?: "primary" | "secondary" | "ghost" }) { return <button type={type} className={`button button-${variant} ${className}`} onClick={onClick} disabled={disabled} {...props}>{children}</button>; }
function StatusPill({ children, color = "cyan" }: { children: ReactNode; color?: string }) { return <span className={`statusPill ${color}`}>{children}</span>; }
function StatCard({ label, value, suffix, trend, icon: Icon }: { label: string; value: string; suffix?: string; trend?: string; icon: typeof Activity }) { return <GlassCard className="statCard"><div className="statTop"><span>{label}</span><span className="statIcon"><Icon size={16}/></span></div><div className="statValue">{value}<small>{suffix}</small></div>{trend && <div className="statHint"><span className="tinyTrend">↗</span>{trend}</div>}</GlassCard>; }
function EmptyState({ title, detail, action }: { title: string; detail: string; action?: ReactNode }) { return <div className="emptyState"><CircleHelp size={20}/><strong>{title}</strong><p>{detail}</p>{action}</div>; }

const homeTrend = [
  { day: "01", intensity: 24 }, { day: "03", intensity: 27 }, { day: "05", intensity: 31 }, { day: "07", intensity: 29 }, { day: "09", intensity: 39 }, { day: "11", intensity: 43 }, { day: "13", intensity: 41 },
];
function ActivityChart(){const points=homeTrend.map((item,i)=>({x:42+i*48,y:174-item.intensity*3.25,label:item.day,value:item.intensity}));const line=points.map((p,i)=>`${i?"L":"M"}${p.x},${p.y}`).join(" ");const area=`${line} L ${points.at(-1)!.x},184 L ${points[0]!.x},184 Z`;return <div className="chartBox"><svg viewBox="0 0 720 210" preserveAspectRatio="none" role="img" aria-label="Illustrative local exploration activity across fourteen days"><title>Illustrative local exploration activity</title>{[35,75,115,155].map(y=><line key={y} x1="36" x2="692" y1={y} y2={y} stroke="#243049" strokeDasharray="4 6"/>)}<path d={area} fill="url(#activityFill)"/><defs><linearGradient id="activityFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#68dbe5" stopOpacity=".27"/><stop offset="100%" stopColor="#68dbe5" stopOpacity="0"/></linearGradient></defs><path d={line} fill="none" stroke="#6edce8" strokeWidth="2.5" vectorEffect="non-scaling-stroke"/>{points.map(p=><g key={p.label}><circle cx={p.x} cy={p.y} r="3" fill="#a9f2f0"><title>{`${p.label}: illustrative activity ${p.value}`}</title></circle><text x={p.x} y="202" textAnchor="middle" fill="#74819d" fontSize="9">{p.label}</text></g>)}</svg></div>}
function TrajectoryChart({samples}:{samples:{x:number;y:number}[]}){const maxX=Math.max(1,...samples.map(p=>p.x)),maxY=Math.max(1,...samples.map(p=>p.y));const points=samples.map(p=>({x:48+p.x/maxX*650,y:255-p.y/maxY*218,source:p}));const path=points.map((p,i)=>`${i?"L":"M"}${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(" ");return <div className="physicsPlot"><svg viewBox="0 0 720 300" preserveAspectRatio="none" role="img" aria-label="Ideal projectile trajectory plot. Horizontal position in meters and height in meters."><title>Ideal projectile trajectory</title>{[0,1,2,3,4].map(i=><g key={i}><line x1="48" x2="700" y1={30+i*54} y2={30+i*54} stroke="#243049" strokeDasharray="4 6"/><text x="39" y={34+i*54} textAnchor="end" fill="#74819d" fontSize="9">{(maxY*(4-i)/4).toFixed(1)}</text></g>)}<line x1="48" x2="700" y1="255" y2="255" stroke="#35405a"/><path d={path} fill="none" stroke="#67dbe5" strokeWidth="2.5" vectorEffect="non-scaling-stroke"/><text x="374" y="292" textAnchor="middle" fill="#8290a9" fontSize="10">Horizontal position · m</text><text x="12" y="142" transform="rotate(-90 12 142)" textAnchor="middle" fill="#8290a9" fontSize="10">Height · m</text>{points.filter((_,i)=>i===0||i===points.length-1).map((p,i)=><circle key={i} cx={p.x} cy={p.y} r="3.5" fill="#bcf6f5"><title>{`x ${p.source.x.toFixed(2)} m, y ${p.source.y.toFixed(2)} m`}</title></circle>)}</svg></div>}
function MomentChart({values}:{values:{case:string;moment:number}[]}){const max=Math.max(1,...values.map(v=>v.moment));return <div className="engPlot"><svg viewBox="0 0 720 260" preserveAspectRatio="none" role="img" aria-label="Bar chart comparing model lever-arm length and idealized moment"><title>Idealized moment by lever-arm length</title>{[0,1,2,3].map(i=><line key={i} x1="52" x2="700" y1={25+i*52} y2={25+i*52} stroke="#243049" strokeDasharray="4 6"/>)}{values.map((v,i)=>{const x=95+i*150;const h=v.moment/max*182;return <g key={v.case}><rect x={x} y={218-h} width="72" height={h} rx="4" fill="#8e85f2"><title>{`${v.case} lever arm: ${v.moment.toFixed(0)} N·m`}</title></rect><text x={x+36} y="243" textAnchor="middle" fill="#8995ad" fontSize="11">{v.case}</text></g>})}</svg></div>}
function MathFunctionChart({rows,yMin,yMax}:{rows:{x:number;y:number}[];yMin:number;yMax:number}){const points=rows.map(p=>({x:50+(p.x+6.3)/12.6*650,y:260-(p.y-yMin)/(yMax-yMin)*225}));const path=points.map((p,i)=>`${i?"L":"M"}${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(" ");const zeroY=260-(0-yMin)/(yMax-yMin)*225;return <div className="mathPlot"><svg viewBox="0 0 720 310" preserveAspectRatio="none" role="img" aria-label="Reference graph for the selected mathematical function"><title>Function reference plot</title>{[0,1,2,3,4].map(i=>{const y=30+i*55;return <line key={i} x1="50" x2="700" y1={y} y2={y} stroke="#243049" strokeDasharray="4 6"/>})}<line x1="50" x2="700" y1={Math.max(30,Math.min(250,zeroY))} y2={Math.max(30,Math.min(250,zeroY))} stroke="#53607a"/><line x1="375" x2="375" y1="28" y2="260" stroke="#35405a"/><path d={path} fill="none" stroke="#aa9fff" strokeWidth="2.5" vectorEffect="non-scaling-stroke"/><text x="50" y="286" fill="#8995ad" fontSize="10">−6.3</text><text x="375" y="286" textAnchor="middle" fill="#8995ad" fontSize="10">0</text><text x="700" y="286" textAnchor="end" fill="#8995ad" fontSize="10">6.3</text><text x="375" y="304" textAnchor="middle" fill="#8290a9" fontSize="10">x · dimensionless</text></svg></div>}


